def reusable_probe(s: Settings, cve: str) -> dict[str, Any] | None:
    """An independent-porter probe already calibrated on the 4.2.30 tree (C1 holds and its
    own line came out AFFECTED or NOT_AFFECTED_PROVEN). Hand-written probes and probes that
    ended UNPROVEN are not reused: the campaign runs the porter for those."""
    from heirloom.lines.matrix import probe_sources

    ledgers = [s.ledger_path, *(s.root / p for p in PROBE_LEDGERS)]
    chosen, bodies, _ = probe_sources([p for p in ledgers if p.exists()])
    src = chosen.get(cve)
    if src is None or src.origin != "porter" or src.sha not in bodies:
        return None
    if src.line_verdict not in ("AFFECTED", "NOT_AFFECTED_PROVEN"):
        return None
    record, where = probe_record([p for p in ledgers if p.exists()], src.sha)
    return {
        **record,
        **bodies[src.sha],
        "origin": src.origin,
        # Where the porter wrote and calibrated it (not a later reuse of it).
        "reused_from": where or {"ledger": src.ledger, "line": src.line, "run": src.run_id},
    }


def probe_record(ledgers: list[Path], sha: str) -> tuple[dict[str, Any], dict[str, str]]:
    """The porter's own probe output (model, leakage check, ...) for a probe sha, not a
    later reuse's copy, and where it was made (ledger, line, run)."""
    import sqlite3

    for ledger in ledgers:
        conn = sqlite3.connect(f"file:{ledger}?mode=ro", uri=True)
        try:
            for out, line, run in conn.execute(
                "SELECT output_json, line, run_id FROM stages WHERE stage='probe' "
                "AND status='done' AND output_json LIKE ? ORDER BY finished_at",
                (f'%"{sha}"%',),
            ):
                data = json.loads(out or "{}")
                if data.get("sha") == sha and "reused_from" not in data:
                    return dict(data), {"ledger": str(ledger), "line": line, "run": run}
        finally:
            conn.close()
    return {}, {}


def _pr_number(url: str) -> int | None:
    m = re.search(r"/pull/(\d+)", url or "")
    return int(m[1]) if m else None


